    payload_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, sent_at TEXT
  );
  CREATE INDEX outbox_org ON outbox(org_id,created_at,id);
  CREATE INDEX outbox_user ON outbox(user_id,created_at,id);`);
}

import {AppError,roleAllows,scopeAllows} from '@crew/shared';
export function createPermissions(ctx) {
  const {db}=ctx;
  const deny=message=>{throw new AppError('FORBIDDEN',message,403);};
  const membership=(userId,orgId)=>db.prepare('SELECT * FROM memberships WHERE user_id=? AND org_id=?').get(userId,orgId)??null;
  function scope(req,permission) {
    if (!req.user) throw new AppError('UNAUTHENTICATED','Please sign in',401);
    if (req.auth?.kind==='token'&&!scopeAllows(req.auth.scopes,permission)) deny('API token lacks '+permission+' scope');
    return true;
  }
  function canOrg(userId,orgId,permission='org:read') {
    const member=membership(userId,orgId);
    return Boolean(member&&roleAllows(member.role,permission));
  }
  function assertOrg(req,orgId,permission='org:read') {
    scope(req,permission);
    const member=membership(req.user.id,orgId);
    if (!member||!roleAllows(member.role,permission)) deny('Organization permission denied');
    return member;
  }
  function project(projectId) {
    if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='projects'").get()) throw new AppError('NOT_FOUND','Project not found',404);
    const row=db.prepare('SELECT * FROM projects WHERE id=?').get(projectId);
    if (!row) throw new AppError('NOT_FOUND','Project not found',404);
    return row;
  }
  function canProject(userId,projectId,permission='project:read') {
    const row=project(projectId);
    const member=membership(userId,row.org_id);
    if (!member||!roleAllows(member.role,permission,{project:true})) return false;
    return member.role!=='guest'||Boolean(db.prepare('SELECT 1 FROM project_guests WHERE project_id=? AND user_id=?').get(projectId,userId));
  }
  function assertProject(req,projectId,permission='project:read') {
    scope(req,permission);
    const row=project(projectId);
    if (!canProject(req.user.id,projectId,permission)) deny('Project permission denied');
    return row;
  }
  function assertSelf(req,userId=req.user?.id,permission='self:read') {
    scope(req,permission);
    if (userId!==req.user.id) deny('This action belongs to another account');
    return req.user;
  }
  function projectIds(userId,orgId) {
    const member=membership(userId,orgId);
    if (!member) return [];
    if (!db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='projects'").get()) return [];
    if (member.role==='guest') return db.prepare('SELECT p.id FROM projects p JOIN project_guests g ON p.id=g.project_id WHERE p.org_id=? AND g.user_id=? ORDER BY p.id').all(orgId,userId).map(r=>r.id);
    return db.prepare('SELECT id FROM projects WHERE org_id=? ORDER BY id').all(orgId).map(r=>r.id);
  }
  return {scope,membership,canOrg,assertOrg,canProject,assertProject,assertSelf,projectIds};
}
export function requirePermission(ctx,permission,resolve) {
  return (req,res,next)=>{
    try {const target=resolve(req);if(target.projectId)ctx.permissions.assertProject(req,target.projectId,permission);else if(target.orgId)ctx.permissions.assertOrg(req,target.orgId,permission);else ctx.permissions.assertSelf(req,target.userId,permission);next();} catch(error){next(error);}
  };
}

import {AppError,orgInput,memberInput,roleInput,roleAllows} from '@crew/shared';
export const publicOrg=row=>({id:row.id,name:row.name,createdAt:row.created_at,updatedAt:row.updated_at,...(row.role?{role:row.role}:{})});
export const publicMember=row=>({userId:row.user_id,orgId:row.org_id,role:row.role,name:row.name,email:row.email,createdAt:row.created_at,updatedAt:row.updated_at});
export function registerOrganizations(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  function emit(req,orgId,entityId,action,before,after) {ctx.bus.emit({actorId:req.user.id,orgId,projectId:null,entityType:'organization',entityId,action,before:before??null,after:after??null,time:ctx.now()});}
  function organization(id) {const row=db.prepare('SELECT * FROM organizations WHERE id=?').get(id);if(!row)throw new AppError('NOT_FOUND','Organization not found',404);return row;}
  app.get('/api/v1/orgs',requireAuth,(req,res)=>{
    p.scope(req,'org:read');
    const rows=db.prepare('SELECT o.*,m.role FROM organizations o JOIN memberships m ON m.org_id=o.id WHERE m.user_id=? ORDER BY o.created_at,o.id').all(req.user.id);
    res.json(ctx.paginate(rows.map(publicOrg),req.query));
  });
  app.post('/api/v1/orgs',requireAuth,(req,res)=>{
    p.scope(req,'org:manage');
    const {name}=orgInput(req.body);
    const id=ctx.id(),time=ctx.now();
    const result=ctx.transaction(()=>{
      db.prepare('INSERT INTO organizations VALUES (?,?,?,?)').run(id,name,time,time);
      db.prepare('INSERT INTO memberships VALUES (?,?,?,?,?)').run(id,req.user.id,'owner',time,time);
      return publicOrg({...organization(id),role:'owner'});
    });
    emit(req,id,id,'created',null,result);
    res.status(201).json({organization:result});
  });
  app.get('/api/v1/orgs/:orgId',requireAuth,(req,res)=>{const member=p.assertOrg(req,req.params.orgId);res.json({organization:publicOrg({...organization(req.params.orgId),role:member.role}),permissions:Object.fromEntries(['org:manage','members:manage','teams:manage','invites:manage','audit:read'].map(name=>[name,roleAllows(member.role,name)]))});});
  app.patch('/api/v1/orgs/:orgId',requireAuth,(req,res)=>{
    const {orgId}=req.params;p.assertOrg(req,orgId,'org:manage');const before=publicOrg(organization(orgId));const {name}=orgInput(req.body);
    db.prepare('UPDATE organizations SET name=?,updated_at=? WHERE id=?').run(name,ctx.now(),orgId);
    const after=publicOrg(organization(orgId));emit(req,orgId,orgId,'updated',before,after);res.json({organization:after});
  });
  app.get('/api/v1/orgs/:orgId/members',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId);const rows=db.prepare('SELECT m.*,u.name,u.email FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.org_id=? ORDER BY m.created_at,m.user_id').all(req.params.orgId);
    res.json(ctx.paginate(rows.map(publicMember),req.query,'userId'));
  });
  app.post('/api/v1/orgs/:orgId/members',requireAuth,(req,res)=>{
    const {orgId}=req.params;const actor=p.assertOrg(req,orgId,'members:manage');const input=memberInput(req.body);
    if(input.role==='owner'&&actor.role!=='owner')throw new AppError('FORBIDDEN','Only owners can appoint an owner',403);
    if(!db.prepare('SELECT id FROM users WHERE id=?').get(input.userId))throw new AppError('NOT_FOUND','User not found',404);
    if(p.membership(input.userId,orgId))throw new AppError('CONFLICT','User is already a member',409);
    const time=ctx.now();db.prepare('INSERT INTO memberships VALUES (?,?,?,?,?)').run(orgId,input.userId,input.role,time,time);
    emit(req,orgId,input.userId,'member_added',null,input);res.status(201).json({membership:{orgId,...input}});
  });
  function editable(req) {
    const {orgId,userId}=req.params;const actor=p.assertOrg(req,orgId,'members:manage');const target=p.membership(userId,orgId);
    if(!target)throw new AppError('NOT_FOUND','Membership not found',404);
    if(target.role==='owner'&&actor.role!=='owner')throw new AppError('FORBIDDEN','Only an owner can manage owners',403);
    return target;
  }
  function ensureOwner(target,nextRole) {
    if(target.role==='owner'&&nextRole!=='owner'&&db.prepare("SELECT count(*) AS n FROM memberships WHERE org_id=? AND role='owner'").get(target.org_id).n<=1)throw new AppError('CONFLICT','An organization must retain an owner',409);
  }
  app.patch('/api/v1/orgs/:orgId/members/:userId',requireAuth,(req,res)=>{
    const target=editable(req);const {role}=roleInput(req.body);const actor=p.membership(req.user.id,target.org_id);
    if(role==='owner'&&actor.role!=='owner')throw new AppError('FORBIDDEN','Only owners can appoint an owner',403);
    ensureOwner(target,role);db.prepare('UPDATE memberships SET role=?,updated_at=? WHERE org_id=? AND user_id=?').run(role,ctx.now(),target.org_id,target.user_id);
    emit(req,target.org_id,target.user_id,'member_role_changed',{role:target.role},{role});res.json({membership:{orgId:target.org_id,userId:target.user_id,role}});
  });
  app.delete('/api/v1/orgs/:orgId/members/:userId',requireAuth,(req,res)=>{
    const target=editable(req);ensureOwner(target,null);
    ctx.transaction(()=>{db.prepare('DELETE FROM team_members WHERE user_id=? AND team_id IN (SELECT id FROM teams WHERE org_id=?)').run(target.user_id,target.org_id);if(db.prepare("SELECT name FROM sqlite_master WHERE name='projects'").get())db.prepare('DELETE FROM project_guests WHERE user_id=? AND project_id IN (SELECT id FROM projects WHERE org_id=?)').run(target.user_id,target.org_id);db.prepare('DELETE FROM memberships WHERE org_id=? AND user_id=?').run(target.org_id,target.user_id);});
    emit(req,target.org_id,target.user_id,'member_removed',{role:target.role},null);res.json({ok:true});
  });
  app.get('/api/v1/projects/:projectId/guests',requireAuth,(req,res)=>{p.assertProject(req,req.params.projectId,'project:manage');res.json(ctx.paginate(db.prepare('SELECT g.*,u.name,u.email FROM project_guests g JOIN users u ON u.id=g.user_id WHERE project_id=? ORDER BY g.user_id').all(req.params.projectId).map(row=>({userId:row.user_id,name:row.name,email:row.email,createdAt:row.created_at})),req.query,'userId'));});
  app.post('/api/v1/projects/:projectId/guests',requireAuth,(req,res)=>{
    const project=p.assertProject(req,req.params.projectId,'project:manage');const {userId}=memberInput({...req.body,role:'guest'});const member=p.membership(userId,project.org_id);
    if(!member||member.role!=='guest')throw new AppError('VALIDATION','User must be a guest in this organization',422);
    if(db.prepare('SELECT 1 FROM project_guests WHERE project_id=? AND user_id=?').get(project.id,userId))throw new AppError('CONFLICT','Guest already has project access',409);
    db.prepare('INSERT INTO project_guests VALUES (?,?,?)').run(project.id,userId,ctx.now());ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'project',entityId:project.id,action:'guest_added',before:null,after:{userId},time:ctx.now()});res.status(201).json({projectId:project.id,userId});
  });
  app.delete('/api/v1/projects/:projectId/guests/:userId',requireAuth,(req,res)=>{const project=p.assertProject(req,req.params.projectId,'project:manage');const result=db.prepare('DELETE FROM project_guests WHERE project_id=? AND user_id=?').run(project.id,req.params.userId);if(!result.changes)throw new AppError('NOT_FOUND','Project guest not found',404);ctx.bus.emit({actorId:req.user.id,orgId:project.org_id,projectId:project.id,entityType:'project',entityId:project.id,action:'guest_removed',before:{userId:req.params.userId},after:null,time:ctx.now()});res.json({ok:true});});
}

import {AppError,email} from '@crew/shared';
export function enqueueOutbox(ctx,input) {
  if (!['invite','reset','digest'].includes(input.kind)) throw new AppError('VALIDATION','Unknown outbox kind',422);
  const row={id:ctx.id(),orgId:input.orgId??null,userId:input.userId??null,kind:input.kind,toEmail:email(input.toEmail),subject:String(input.subject),textBody:String(input.textBody),payload:input.payload??{},createdAt:ctx.now(),sentAt:null};
  ctx.db.prepare('INSERT INTO outbox(id,org_id,user_id,kind,to_email,subject,text_body,payload_json,created_at,sent_at) VALUES (?,?,?,?,?,?,?,?,?,NULL)').run(row.id,row.orgId,row.userId,row.kind,row.toEmail,row.subject,row.textBody,JSON.stringify(row.payload),row.createdAt);
  return row;
}
export const publicOutbox=row=>({id:row.id,orgId:row.org_id,userId:row.user_id,kind:row.kind,toEmail:row.to_email,subject:row.subject,textBody:row.text_body,payload:JSON.parse(row.payload_json),createdAt:row.created_at,sentAt:row.sent_at});

import {createPermissions} from '../../http/middleware/permissions.js';
import {registerOrganizations} from './orgs.js';
import {registerTeams} from './teams.js';
import {enqueueOutbox} from './outbox.js';
export function registerRoutes(ctx) {
  ctx.permissions=createPermissions(ctx);
  ctx.enqueueOutbox=input=>enqueueOutbox(ctx,input);
  registerOrganizations(ctx);
  registerTeams(ctx);
}

import {AppError,teamInput,fields,text} from '@crew/shared';
export const publicTeam=row=>({id:row.id,orgId:row.org_id,name:row.name,description:row.description,createdAt:row.created_at,updatedAt:row.updated_at});
export function registerTeams(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  function team(id) {const row=db.prepare('SELECT * FROM teams WHERE id=?').get(id);if(!row)throw new AppError('NOT_FOUND','Team not found',404);return row;}
  function event(req,row,action,before,after) {ctx.bus.emit({actorId:req.user.id,orgId:row.org_id,projectId:null,entityType:'team',entityId:row.id,action,before:before??null,after:after??null,time:ctx.now()});}
  function unique(orgId,name,id='') {if(db.prepare('SELECT id FROM teams WHERE org_id=? AND name=? AND id<>?').get(orgId,name,id))throw new AppError('CONFLICT','A team with this name already exists',409);}
  app.get('/api/v1/orgs/:orgId/teams',requireAuth,(req,res)=>{p.assertOrg(req,req.params.orgId);res.json(ctx.paginate(db.prepare('SELECT * FROM teams WHERE org_id=? ORDER BY created_at,id').all(req.params.orgId).map(publicTeam),req.query));});
  app.post('/api/v1/orgs/:orgId/teams',requireAuth,(req,res)=>{
    p.assertOrg(req,req.params.orgId,'teams:manage');const input=teamInput(req.body);unique(req.params.orgId,input.name);const id=ctx.id(),time=ctx.now();
    db.prepare('INSERT INTO teams VALUES (?,?,?,?,?,?)').run(id,req.params.orgId,input.name,input.description,time,time);const row=team(id);event(req,row,'created',null,publicTeam(row));res.status(201).json({team:publicTeam(row)});
  });
  app.get('/api/v1/teams/:teamId',requireAuth,(req,res)=>{const row=team(req.params.teamId);p.assertOrg(req,row.org_id);res.json({team:publicTeam(row)});});
  app.patch('/api/v1/teams/:teamId',requireAuth,(req,res)=>{
    const row=team(req.params.teamId);p.assertOrg(req,row.org_id,'teams:manage');const input=teamInput(req.body);unique(row.org_id,input.name,row.id);db.prepare('UPDATE teams SET name=?,description=?,updated_at=? WHERE id=?').run(input.name,input.description,ctx.now(),row.id);const after=publicTeam(team(row.id));event(req,row,'updated',publicTeam(row),after);res.json({team:after});
  });
  app.delete('/api/v1/teams/:teamId',requireAuth,(req,res)=>{const row=team(req.params.teamId);p.assertOrg(req,row.org_id,'teams:manage');db.prepare('DELETE FROM teams WHERE id=?').run(row.id);event(req,row,'deleted',publicTeam(row),null);res.json({ok:true});});
  app.get('/api/v1/teams/:teamId/members',requireAuth,(req,res)=>{const row=team(req.params.teamId);p.assertOrg(req,row.org_id);const members=db.prepare('SELECT tm.*,u.email,u.name,m.role FROM team_members tm JOIN users u ON u.id=tm.user_id JOIN memberships m ON m.user_id=tm.user_id AND m.org_id=? WHERE tm.team_id=? ORDER BY tm.created_at,tm.user_id').all(row.org_id,row.id);res.json(ctx.paginate(members.map(m=>({userId:m.user_id,name:m.name,email:m.email,role:m.role,createdAt:m.created_at})),req.query,'userId'));});
  app.post('/api/v1/teams/:teamId/members',requireAuth,(req,res)=>{
    const row=team(req.params.teamId);p.assertOrg(req,row.org_id,'teams:manage');fields(req.body,['userId']);const userId=text(req.body.userId,'userId');if(!p.membership(userId,row.org_id))throw new AppError('VALIDATION','Team members must belong to the organization',422);
    if(db.prepare('SELECT 1 FROM team_members WHERE team_id=? AND user_id=?').get(row.id,userId))throw new AppError('CONFLICT','User is already on the team',409);db.prepare('INSERT INTO team_members VALUES (?,?,?)').run(row.id,userId,ctx.now());event(req,row,'member_added',null,{userId});res.status(201).json({teamId:row.id,userId});
  });
  app.delete('/api/v1/teams/:teamId/members/:userId',requireAuth,(req,res)=>{const row=team(req.params.teamId);p.assertOrg(req,row.org_id,'teams:manage');const result=db.prepare('DELETE FROM team_members WHERE team_id=? AND user_id=?').run(row.id,req.params.userId);if(!result.changes)throw new AppError('NOT_FOUND','Team member not found',404);event(req,row,'member_removed',{userId:req.params.userId},null);res.json({ok:true});});
}

import {test,beforeEach,afterEach} from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
let s,owner,other,outsider,org,otherId,outsiderId;
beforeEach(async()=>{
  s=await testServer();owner=s.agent();other=s.agent();outsider=s.agent();
  await owner('POST','/auth/signup',{name:'Owner',email:'owner@example.com',password:'correct-horse-123'});
  otherId=(await other('POST','/auth/signup',{name:'Colleague',email:'other@example.com',password:'correct-horse-123'})).data.user.id;
  outsiderId=(await outsider('POST','/auth/signup',{name:'Stranger',email:'stranger@example.com',password:'correct-horse-123'})).data.user.id;
  org=(await owner('POST','/orgs',{name:'Crew'})).data.organization;
});
afterEach(async()=>{await s.close();});
test('organization creation returns owner and lists only memberships',async()=>{assert.equal(org.role,'owner');assert.equal((await owner('GET','/orgs')).data.items.length,1);assert.deepEqual((await outsider('GET','/orgs')).data.items,[]);});
test('organization rename persists and validates fields',async()=>{assert.equal((await owner('PATCH','/orgs/'+org.id,{name:'New Crew'})).data.organization.name,'New Crew');assert.equal((await owner('PATCH','/orgs/'+org.id,{name:''})).status,422);});
test('outsiders cannot read organization or its roster',async()=>{assert.equal((await outsider('GET','/orgs/'+org.id)).status,403);assert.equal((await outsider('GET','/orgs/'+org.id+'/members')).status,403);});
test('membership creation detects duplicate and missing accounts',async()=>{assert.equal((await owner('POST','/orgs/'+org.id+'/members',{userId:otherId,role:'member'})).status,201);assert.equal((await owner('POST','/orgs/'+org.id+'/members',{userId:otherId})).status,409);assert.equal((await owner('POST','/orgs/'+org.id+'/members',{userId:'missing'})).status,404);});
test('member reads roster but cannot rename or appoint members',async()=>{await owner('POST','/orgs/'+org.id+'/members',{userId:otherId});assert.equal((await other('GET','/orgs/'+org.id+'/members')).status,200);assert.equal((await other('PATCH','/orgs/'+org.id,{name:'No'})).status,403);assert.equal((await other('POST','/orgs/'+org.id+'/members',{userId:outsiderId})).status,403);});
test('last owner cannot be demoted or removed',async()=>{const id=(await owner('GET','/me')).data.user.id;assert.equal((await owner('PATCH','/orgs/'+org.id+'/members/'+id,{role:'member'})).status,409);assert.equal((await owner('DELETE','/orgs/'+org.id+'/members/'+id)).status,409);});
test('admin manages members but cannot appoint or alter owners',async()=>{await owner('POST','/orgs/'+org.id+'/members',{userId:otherId,role:'admin'});const id=(await owner('GET','/me')).data.user.id;assert.equal((await other('POST','/orgs/'+org.id+'/members',{userId:outsiderId,role:'owner'})).status,403);assert.equal((await other('PATCH','/orgs/'+org.id+'/members/'+id,{role:'member'})).status,403);});
test('owner can transfer ownership before leaving',async()=>{await owner('POST','/orgs/'+org.id+'/members',{userId:otherId,role:'owner'});const id=(await owner('GET','/me')).data.user.id;assert.equal((await owner('DELETE','/orgs/'+org.id+'/members/'+id)).status,200);assert.equal((await other('GET','/orgs/'+org.id)).data.organization.role,'owner');});
test('teams support create read update and delete',async()=>{const t=(await owner('POST','/orgs/'+org.id+'/teams',{name:'Design',description:'Ship'})).data.team;assert.equal((await owner('GET','/teams/'+t.id)).data.team.description,'Ship');assert.equal((await owner('PATCH','/teams/'+t.id,{name:'Product',description:'Build'})).data.team.name,'Product');assert.equal((await owner('DELETE','/teams/'+t.id)).status,200);assert.equal((await owner('GET','/teams/'+t.id)).status,404);});
test('team names are unique inside organization',async()=>{await owner('POST','/orgs/'+org.id+'/teams',{name:'Design'});assert.equal((await owner('POST','/orgs/'+org.id+'/teams',{name:'Design'})).status,409);});
