export const ROLES = Object.freeze(['owner','admin','member','guest']);
export const PERMISSIONS = Object.freeze([
  'self:read','self:write','org:read','org:manage','members:manage','teams:manage',
  'invites:manage','audit:read','project:read','project:write','project:manage',
  'issue:write','comment:write','attachment:write','insight:read','insight:write',
  'export:read','import:write'
]);
const administration = new Set(['org:manage','members:manage','teams:manage','invites:manage','audit:read','project:manage']);
const guestPermissions = new Set(['project:read','comment:write','insight:read']);
export function roleAllows(role,permission,{project=false}={}) {
  if (!ROLES.includes(role) || !PERMISSIONS.includes(permission)) return false;
  if (role==='owner' || role==='admin') return true;
  if (permission==='org:read') return true;
  if (role==='guest') return project && guestPermissions.has(permission);
  return !administration.has(permission);
}
export function scopeAllows(scopes,permission) {
  if (!Array.isArray(scopes) || !PERMISSIONS.includes(permission)) return false;
  return scopes.includes('*') || scopes.includes(permission) || scopes.includes(permission.split(':')[0]+':*');
}
export function validScope(scope) {
  return scope==='*' || PERMISSIONS.includes(scope) || (typeof scope==='string' && scope.endsWith(':*') && PERMISSIONS.some(p=>p.startsWith(scope.slice(0,-1))));
}

import {fields,text,choice,email,integer,uniqueIds} from '../validate.js';
import {ROLES,validScope} from '../permissions.js';
import {validation} from '../errors.js';
export function orgInput(body) {
  fields(body,['name']);
  return {name:text(body.name,'name',{max:120})};
}
export function memberInput(body) {
  fields(body,['userId','role']);
  return {userId:text(body.userId,'userId'),role:choice(body.role,'role',ROLES,'member')};
}
export function roleInput(body) {
  fields(body,['role']);
  return {role:choice(body.role,'role',ROLES)};
}
export function teamInput(body) {
  fields(body,['name','description']);
  return {name:text(body.name,'name',{max:120}),description:text(body.description??'','description',{min:0,max:2000})};
}
export function inviteInput(body) {
  fields(body,['email','role','expiresInHours','projectIds']);
  return {email:email(body.email),role:choice(body.role,'role',ROLES,'member'),expiresInHours:integer(body.expiresInHours??168,'expiresInHours',{min:1,max:720}),projectIds:body.projectIds===undefined?[]:uniqueIds(body.projectIds,'projectIds')};
}
export function tokenInput(body) {
  fields(body,['name','scopes','expiresInDays']);
  const scopes=body.scopes??['self:read','org:read','project:read','insight:read'];
  if (!Array.isArray(scopes)||!scopes.length||scopes.length>40||scopes.some(s=>!validScope(s))) throw validation({scopes:'Choose known permission scopes or a namespace wildcard'});
  return {name:text(body.name,'name',{max:100}),scopes:[...new Set(scopes)],expiresInDays:body.expiresInDays==null?null:integer(body.expiresInDays,'expiresInDays',{min:1,max:365})};
}

